#![allow(clippy::unwrap_used, clippy::panic)]
//! Cross-language parity: the same frozen vectors the TypeScript encoder
//! must reproduce (generated by an independent oracle, never by either side).
use super::policy_canonical::*;

const GOLDEN: &str = include_str!("../../../../../protocol/computer-use/policy.v1.golden");

fn golden(key: &str) -> Vec<u8> {
    let hex = GOLDEN
        .lines()
        .find_map(|line| line.strip_prefix(key)?.strip_prefix('='))
        .unwrap_or_else(|| panic!("missing golden {key}"));
    hex.as_bytes()
        .chunks(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
fn digest(name: &str) -> [u8; 32] {
    golden(&format!("{name}.sha256")).try_into().unwrap()
}

const NAMES: [&str; 3] = ["minimal", "selectors", "utf8_order"];

#[test]
fn golden_vectors_decode_and_reencode_exactly() {
    for name in NAMES {
        let bytes = golden(&format!("{name}.canonical"));
        let policy = CanonicalPolicy::decode(&bytes).unwrap();
        assert_eq!(policy.encode(), bytes, "{name}");
        assert_eq!(digest(name).len(), 32);
    }
    let selectors = CanonicalPolicy::decode(&golden("selectors.canonical")).unwrap();
    assert_eq!(selectors.revision, u64::MAX);
    assert_eq!(selectors.delivery, Delivery::Background);
    assert_eq!(selectors.disallowed.len(), 4);
    assert_eq!(selectors.disallowed[0].platform, "linux");
    let order = CanonicalPolicy::decode(&golden("utf8_order.canonical")).unwrap();
    let values: Vec<_> = order.disallowed.iter().map(|a| a.value.as_str()).collect();
    assert_eq!(
        values,
        [
            "/Apps/Caf\u{e9}.app",
            "/Apps/\u{ff5e}.app",
            "/Apps/\u{1f600}.app"
        ]
    );
}

#[test]
fn golden_digests_verify_and_a_mismatch_refuses() {
    for name in NAMES {
        let bytes = golden(&format!("{name}.canonical"));
        assert!(
            CanonicalPolicy::verify(&bytes, digest(name)).is_ok(),
            "{name}"
        );
    }
    let mut wrong = digest("minimal");
    wrong[0] ^= 1;
    assert_eq!(
        CanonicalPolicy::verify(&golden("minimal.canonical"), wrong),
        Err(CanonicalRefusal::DigestMismatch)
    );
}

#[test]
fn every_noncanonical_form_refuses() {
    let text = String::from_utf8(golden("minimal.canonical")).unwrap();
    let mutate = |from: &str, to: &str| text.replacen(from, to, 1).into_bytes();
    let selectors = String::from_utf8(golden("selectors.canonical")).unwrap();
    let swapped = {
        let mut lines: Vec<_> = selectors.lines().collect();
        lines.swap(9, 10);
        format!("{}\n", lines.join("\n")).into_bytes()
    };
    let duplicated = {
        let mut lines: Vec<_> = selectors.lines().collect();
        lines[10] = lines[9];
        format!("{}\n", lines.join("\n")).into_bytes()
    };
    let cases: Vec<(Vec<u8>, CanonicalRefusal)> = vec![
        (Vec::new(), CanonicalRefusal::Oversized),
        (vec![b'x'; 64 * 1024 + 1], CanonicalRefusal::Oversized),
        (
            mutate("revision=1", "revision=01"),
            CanonicalRefusal::Malformed,
        ),
        (
            mutate("enabled=0", "enabled=2"),
            CanonicalRefusal::Malformed,
        ),
        (
            mutate("check_in_ms=600000", "check_in_ms=59999"),
            CanonicalRefusal::OutOfRange,
        ),
        (
            mutate("action_timeout_ms=900000", "action_timeout_ms=3600001"),
            CanonicalRefusal::OutOfRange,
        ),
        (
            mutate("delivery=foreground", "delivery=auto"),
            CanonicalRefusal::Malformed,
        ),
        (
            mutate("authority=authority-1", "authority=bad id"),
            CanonicalRefusal::Malformed,
        ),
        (
            mutate("disallowed=0", "disallowed=1"),
            CanonicalRefusal::Malformed,
        ),
        (mutate("v1\n", "v2\n"), CanonicalRefusal::Malformed),
        (
            text.trim_end().as_bytes().to_vec(),
            CanonicalRefusal::Malformed,
        ),
        (
            format!("{text}\n").into_bytes(),
            CanonicalRefusal::Malformed,
        ),
        (
            format!("{text}app=macos\tpath\t/x\n").into_bytes(),
            CanonicalRefusal::Malformed,
        ),
        (swapped, CanonicalRefusal::UnsortedOrDuplicate),
        (duplicated, CanonicalRefusal::UnsortedOrDuplicate),
        (
            selectors
                .replacen("macos\tpath", "macos\taumid", 1)
                .into_bytes(),
            CanonicalRefusal::Malformed,
        ),
        (vec![0xff; 8], CanonicalRefusal::Malformed),
    ];
    for (bytes, refusal) in cases {
        assert_eq!(
            CanonicalPolicy::decode(&bytes),
            Err(refusal),
            "{:?}",
            String::from_utf8_lossy(&bytes)
        );
    }
}
